// Now compile into flat locations array with automatic slug generation, nearby linking, and deduplication
console.log("Compiling master locations dataset...")

const allCities = []
const slugMap = new Map()

// First pass: register all cities from statesData
for (const stateGroup of statesData) {
  for (const city of stateGroup.cities) {
    const slug = slugify(city.name)
    if (slugMap.has(slug)) {
      console.warn(`WARNING: Duplicate slug found: ${slug} (${city.name}, ${stateGroup.state}). Disambiguating...`)
      const uniqueSlug = `${slug}-${stateGroup.stateSlug}`
      const entry = {
        name: city.name,
        slug: uniqueSlug,
        state: stateGroup.state,
        stateSlug: stateGroup.stateSlug,
        region: stateGroup.region,
        regionSlug: stateGroup.regionSlug,
        tier: city.tier,
        industrialProfile: city.profile,
        keyClusters: city.clusters,
        primaryApplications: city.apps,
      }
      allCities.push(entry)
      slugMap.set(uniqueSlug, entry)
    } else {
      const entry = {
        name: city.name,
        slug,
        state: stateGroup.state,
        stateSlug: stateGroup.stateSlug,
        region: stateGroup.region,
        regionSlug: stateGroup.regionSlug,
        tier: city.tier,
        industrialProfile: city.profile,
        keyClusters: city.clusters,
        primaryApplications: city.apps,
      }
      allCities.push(entry)
      slugMap.set(slug, entry)
    }
  }
}

// Second pass: dynamically calculate smart nearby links
// (Prefers same state, same tier/higher tier, geographically close hubs)
for (const city of allCities) {
  const sameStateCities = allCities.filter((c) => c.stateSlug === city.stateSlug && c.slug !== city.slug)
  const sameRegionCities = allCities.filter((c) => c.regionSlug === city.regionSlug && c.slug !== city.slug && c.stateSlug !== city.stateSlug)

  const nearby = []
  // Add up to 5 from same state
  for (const s of sameStateCities) {
    if (nearby.length < 5) nearby.push(s.slug)
  }
  // Add up to 3 from same region
  for (const r of sameRegionCities) {
    if (nearby.length < 7) nearby.push(r.slug)
  }

  city.nearbySlugs = nearby
}

console.log(`Total cities compiled: ${allCities.length}`)

// Generate the TypeScript/JavaScript dataset file
const outputFilePath = path.resolve(__dirname, "../src/data/locations/dataset.js")

const fileContent = `// ─────────────────────────────────────────────────────────────────────────────
// Master Location Dataset — ${allCities.length} Verified Indian Industrial Locations
// Zohan Enterprises India-wide Local SEO Engine
// ─────────────────────────────────────────────────────────────────────────────

export const rawLocations = ${JSON.stringify(allCities, null, 2)}
`

fs.writeFileSync(outputFilePath, fileContent, "utf-8")
console.log(`Successfully written ${allCities.length} locations to ${outputFilePath}`)
